import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"4.4 控制打扰与验收主动服务","description":"主动模式要安静、有用、可控，并且可以随时关掉。","frontmatter":{"title":"4.4 控制打扰与验收主动服务","description":"主动模式要安静、有用、可控，并且可以随时关掉。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-4/4-4.md","filePath":"delivery/stage-4/4-4.md","lastUpdated":1794015952000}'),r={name:"delivery/stage-4/4-4.md"};function o(n,a,s,d,_,c){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="_4-4-控制打扰与验收主动服务" tabindex="-1">4.4 控制打扰与验收主动服务 <a class="header-anchor" href="#_4-4-控制打扰与验收主动服务" aria-label="Permalink to &quot;4.4 控制打扰与验收主动服务&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现：</strong> 每日上限 0–50、安静时段、冷却时间、聚合窗口、临时暂停和恢复；预算快照显示今日已用、限额和下次允许时间；“需要你”页面集中显示待处理审批。</li><li><strong>仍未完成：</strong> 尚未用 5–10 个真实主动任务验收“平均每个任务打断不超过一次”；没有推送送达统计和长期用户感受记录。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让主动模式安静、有用、可控，并通过真实任务证明它没有变成通知噪音。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>设置每日打断上限、安静时段和同类事件聚合规则。</li><li>提供随时暂停、降级和关闭主动模式的入口，并说明当前处于哪种模式。</li><li>记录每条主动建议是否被接受、忽略或转成任务，以及用户是否觉得有用。</li><li>用 5–10 个真实主动任务检验：平均每个任务打断不超过一次，用户能理解为什么被提醒。</li><li>高风险动作仍然需要审批，手机审批不能被重复使用。</li><li>如果用户开始关闭通知、忽略审批或觉得被打扰，先降低主动性，而不是继续增加功能。</li></ol>',7)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
